    for (const card of sortedCards) {
      const cardEl = createCardEl(card);
      cardList.appendChild(cardEl);
    }
  });

  eventSource.onerror = () => {
    console.warn('SSE connection error, reconnecting...');
    eventSource.close();
    setTimeout(connectSSE, 3000);
  };
}

