  font-weight: 700;
}

#board {
  display: flex;
  gap: 12px;
  padding: 20px;
  overflow-x: auto;
  min-height: calc(100vh - 50px);
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 3px;
