{"content": "* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  color: #172b4d;
}

header {
  background: rgba(0, 0, 0, 0.15);
  padding: 10px 20px;
}

header h1 {
  color: white;
  font-size: 1.25rem;
  font-weight: 700;
}

#board {
  display: flex;
  gap: 12px;
  padding: 20px;
  overflow-x: auto;
  min-height: calc(100vh - 50px);
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 3px;
