// Get end position for a column
async function getEndPosition(columnId) {
  const maxPos = await db.query(
    'SELECT MAX(position) as max_pos FROM cards WHERE column_id = $1',
    [columnId]
  );
  const currentMax = maxPos.rows[0].max_pos;
