{"content": "* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  color: #172b4d;
}

header {
  background: rgba(0, 0, 0, 0.15);
  padding: 10px 20px;
}

header h1 {
  color: white;
  font-size: 1.25rem;
  font-weight: 700;
}

#board {
  display: flex;
  gap: 12px;
  padding: 20px;
  overflow-x: auto;
  min-height: calc(100vh - 50px);
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 3px;
  min-width: 272px;
  max-width: 272px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 90px);
}

.column-header {
  padding: 10px 8px 4px;
  font-weight: 600;
  font-size: 0.95rem;
}

.card-list {
  padding: 4px 8px;
  min-height: 2px;
  flex: 1;
  overflow-y: auto;
}

.card {
  background: white;
  border-radius: 3px;
  padding: 8px;
  margin-bottom: 8px;
  box-shadow: 0 1px 0 #d6dce0;
  cursor: grab;
  word-wrap: break-word;
  transition: opacity 0.15s;
}

.card:hover {
  background: #f4f5f7;
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card-list.drag-over {
  background: rgba(0, 0, 0, 0.04);
  border-radius: 3px;
}

.card-list .drop-indicator {
  height: 4px;
  background: #0079bf;
  border-radius: 2px;
  margin: 2px 0;
  transition: opacity 0.15s;
}

.add-card-form {
  padding: 8px;
}

.add-card-form textarea {
  width: 100%;
  border: none;
  border-radius: 3px;
  padding: 8px;
  font-family: inherit;
  font-size: 0.85rem;
  resize: none;
  min-height: 38px;
  outline: none;
}

.add-card-form textarea:focus {
  box-shadow: 0 0 0 2px #0079bf;
}

.add-card-form button {
  margin-top: 4px;
  padding: 6px 12px;
  background: #0079bf;
  color: white;
  border: none;
  border-radius: 3px;
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 500;
}

.add-card-form button:hover {
  background: #026aa7;
}

.add-card-form .cancel-btn {
  margin-left: 6px;
  background: transparent;
  color: #5e6c84;
}

.add-card-form .cancel-btn:hover {
  background: rgba(0, 0, 0, 0.08);
  color: #172b4d;
}

.add-card-link {
  padding: 8px;
  color: #5e6c84;
  cursor: pointer;
  border-radius: 0 0 3px 3px;
